package com.example.orderprocessing.service;
import com.example.orderprocessing.dto.ProductRequest; import com.example.orderprocessing.entity.Product; import com.example.orderprocessing.repository.ProductRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ProductService { private final ProductRepository repo; public ProductService(ProductRepository repo){this.repo=repo;} public List<Product> all(){return repo.findAll();} public Product get(Long id){return repo.findById(id).orElseThrow();} public Product create(ProductRequest r){return repo.save(new Product(r.sku(),r.name(),r.inventory(),r.price()));} public Product update(Long id,ProductRequest r){Product p=get(id);p.update(r.name(),r.sku(),r.description(),r.price());return repo.save(p);} public Product addStock(Long id,int quantity){if(quantity<1)throw new IllegalArgumentException("Quantity must be positive");Product p=get(id);p.addStock(quantity);return repo.save(p);} public void delete(Long id){repo.deleteById(id);} }
